// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint time, uint blockNum, uint value) public {
        vm.assume(time > c.pastBlockTime());
        vm.assume(value == 10 ether);
        vm.warp(time);
        vm.roll(blockNum);

        // Get the balance before the call
        uint initialBalance = address(c).balance;

        // Fund the contract if needed (it's already funded from constructor)
        if (initialBalance == 0) {
            vm.deal(address(c), 10 ether);
        }

        // Call fallback
        (bool success,) = address(c).call{value: value}("");

        if (success) {
            // The rule: pastBlockTime must equal block.timestamp (not block.timestamp + 1)
            assertTrue(c.pastBlockTime() == time);
        } else {
            // If reverted, pastBlockTime should be unchanged
            assertTrue(c.pastBlockTime() < time);
        }
    }
}

